diagrams.source:
flowchart TB
  OPS(["運用チーム"])
  CS@{ svc: "AWS CloudFormation", label: "✔ B: 変更セットを作って確認" }
  CF@{ svc: "AWS CloudFormation", label: "スタックの更新" }
  S3@{ svc: "Amazon S3", label: "✔ B: 監査ログのバケット（Retain）" }
  RDS@{ svc: "Amazon RDS", label: "DB インスタンス" }
  OPS --> CS
  CS == "確認後に実行" ==> CF
  OPS -. "⚠ A: 直接 UpdateStack、事前に見えない" .-> CF
  CF --> RDS
  CF == "✔ B: 外れても残る" ==> S3
  CF -. "⚠ C・D: 指定なしだと消える（既定は Snapshot ではない）" .-> S3

flowchart TB
  NET@{ svc: "AWS CloudFormation", label: "ネットワークのスタック（サブネット ID を export）" }
  APP@{ svc: "AWS CloudFormation", label: "同じアカウントのアプリのスタック 3 つ" }
  NEW@{ svc: "AWS CloudFormation", label: "別アカウントの新しいスタック" }
  NET -- "ImportValue で import 中" --> APP
  APP == "✔ A: 先に import を外す" ==> NET
  NET == "✔ B: Fn::GetStackOutput で読む" ==> NEW
  NET -. "⚠ C: ImportValue は同じアカウントだけ" .-> NEW
  APP -. "⚠ D・E: import 中は値の変更も削除もできない" .-> NET
